    {
      "id": "P1",
      "expression": "len(input_string) > 0 and len(input_string) <= 10^6",
      "description": "The input string contains only '(' and ')' characters and its length does not exceed 10^6."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "output_length >= 0 and output_length <= len(input_string)",
      "description": "The length of the longest regular bracket subsequence is a non-negative integer not exceeding the length of the input string."
    },
    {
      "id": "Q2",
      "expression": "output_count >= 0",
      "description": "The number of regular bracket subsequences of maximum length is a non-negative integer."
    },
    {
      "id": "Q3",
      "expression": "output_length == 0 and output_count == 1",
      "description": "If there are no regular bracket subsequences, the output is '0 1'."
    }
  ],
  "invariants": []
}
